    if(v('#filterBrand'))q=q.eq('brand',v('#filterBrand')); if(v('#filterModel'))q=q.ilike('model',`%${v('#filterModel')}%`); if(v('#filterCity')||v('#filterCityMobile'))q=q.eq('city',v('#filterCity')||v('#filterCityMobile')); if(v('#filterFuel'))q=q.eq('fuel',v('#filterFuel')); if(v('#filterTransmission'))q=q.eq('transmission',v('#filterTransmission')); if(v('#filterDrivetrain'))q=q.eq('drivetrain',v('#filterDrivetrain')); if(v('#filterColor'))q=q.eq('color',v('#filterColor')); if(v('#filterBody'))q=q.eq('body_type',v('#filterBody'));
